const alert = $input.first().json.body;

// Direct fields from webhook body - ALL using the same pattern
const ruleId = $input.first().json.body.rule_id;
const ruleLevel = $input.first().json.body.rule_level;
const ruleDescription = $input.first().json.body.rule_description;
const alertType = $input.first().json.body.alert_type;
const severity = $input.first().json.body.severity;
const srcIp = $input.first().json.body.src_ip;
const agent = $input.first().json.body.agent;
const timestamp = $input.first().json.body.timestamp;
const fullLog = $input.first().json.body.full_log;

// Email data from full_log (parse it)
let emailSubject = '';
let emailBody = '';
let emailSender = '';
let emailReceiver = '';
let emailDate = '';
let mailbox = '';
let domain = '';

if (fullLog) {
  try {
    const parsed = typeof fullLog === 'string' ? JSON.parse(fullLog) : fullLog;
    emailSubject = parsed.subject || '';
    emailBody = parsed.body || '';
    emailSender = parsed.sender || '';
    emailReceiver = parsed.receiver || '';
    emailDate = parsed.email_date || '';
    mailbox = parsed.mailbox || '';
    domain = parsed.domain || '';
  } catch(e) {}
}

const emailText = `${emailSubject} ${emailBody}`;

// =============================================
// SIMPLE IP MAPPING
// =============================================

let senderIP = 'unknown';
let receiverIP = 'unknown';

// Check sender
if (emailSender.toLowerCase().includes('maria')) senderIP = '192.168.20.4';
if (emailSender.toLowerCase().includes('mostafa')) senderIP = '192.168.20.3';
if (emailSender.toLowerCase().includes('ahmed') || emailSender.toLowerCase().includes('mohammed')) senderIP = '192.168.20.5';

// Check receiver
if (emailReceiver.toLowerCase().includes('maria')) receiverIP = '192.168.20.4';
if (emailReceiver.toLowerCase().includes('mostafa')) receiverIP = '192.168.20.3';
if (emailReceiver.toLowerCase().includes('ahmed') || emailReceiver.toLowerCase().includes('mohammed')) receiverIP = '192.168.20.5';

// Extract URLs from body
const urlRegex = /https?:\/\/[^\s<>"{}|\\^`[\]]+/gi;
const urls = (emailBody || '').match(urlRegex) || [];

// Extract IPs from body
const ipRegex = /[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}/g;
const ips = (emailBody || '').match(ipRegex) || [];

// Extract domains from URLs
const domains = [];
urls.forEach(url => {
  try {
    const domainName = url.replace('https://', '').replace('http://', '').split('/')[0].split(':')[0];
    if (domainName && !domains.includes(domainName)) domains.push(domainName);
  } catch(e) {}
});

// Extract suspicious keywords
const suspiciousKeywords = ['urgent', 'verify', 'account', 'suspended', 'password', 'click', 'login', 'paypal', 'invoice', 'security', 'bank', 'prise', 'check', 'gain', 'money', 'prize'];
const foundKeywords = [];
suspiciousKeywords.forEach(keyword => {
  if (emailText.toLowerCase().includes(keyword)) {
    foundKeywords.push(keyword);
  }
});

// Determine risk level
let riskLevel = 'LOW';
if (urls.length > 0) riskLevel = 'MEDIUM';
if (foundKeywords.length >= 2 || ruleLevel >= 8) riskLevel = 'HIGH';
if (foundKeywords.length >= 4 || ruleLevel >= 12) riskLevel = 'CRITICAL';

return {
  rule_id: ruleId,
  rule_level: ruleLevel,
  rule_description: ruleDescription,
  alert_type: alertType,
  wazuh_severity: severity,
  src_ip: srcIp,
  agent: agent,
  timestamp: timestamp,
  email_sender: emailSender,
  email_receiver: emailReceiver,
  email_subject: emailSubject,
  email_body: emailBody,
  email_text: emailText,
  email_date: emailDate,
  mailbox: mailbox,
  domain: domain,
  sender_ip: senderIP,
  receiver_ip: receiverIP,
  observables: {
    urls: urls,
    domains: domains,
    ips: ips,
    suspicious_keywords: foundKeywords
  },
  risk_level: riskLevel,
  url_count: urls.length,
  ip_count: ips.length,
  keyword_count: foundKeywords.length
};

