const input = $input.first().json;

// Build the description with all extracted data
let description = `## Email Details

| Field | Value |
|-------|-------|
| **Rule ID** | ${input.rule_id || 'N/A'} |
| **Rule Level** | ${input.rule_level || 'N/A'} |
| **Rule Description** | ${input.rule_description || 'N/A'} |
| **Sender** | ${input.email_sender || 'N/A'} |
| **Receiver** | ${input.email_receiver || 'N/A'} |
| **Timestamp** | ${input.timestamp || 'N/A'} |

## Suspicious Indicators

| Type | Values |
|------|--------|
| **IPs** | ${input.observables?.ips?.length ? input.observables.ips.join(', ') : 'None detected'} |
| **URLs** | ${input.observables?.urls?.length ? input.observables.urls.join(', ') : 'None detected'} |
| **Domains** | ${input.observables?.domains?.length ? input.observables.domains.join(', ') : 'None detected'} |
| **Ports** | ${input.observables?.ports?.length ? input.observables.ports.join(', ') : 'None detected'} |

## Detected Suspicious Patterns

${input.observables?.suspicious_texts?.length ? 
  input.observables.suspicious_texts.map(t => `- **${t.category.toUpperCase()}**: "${t.pattern}"`).join('\n') : 
  'No suspicious patterns detected'}

## Full Email Content

\`\`\`
${input.email_text || 'No content'}
\`\`\`
`;

// Build observables array for TheHive
const observables = [];

// Add IPs
if (input.observables?.ips?.length) {
  input.observables.ips.forEach(ip => {
    observables.push({
      dataType: "ip",
      data: ip,
      message: "Suspicious IP detected in email",
      tlp: 2
    });
  });
}

// Add URLs
if (input.observables?.urls?.length) {
  input.observables.urls.forEach(url => {
    observables.push({
      dataType: "url",
      data: url,
      message: "Suspicious URL detected in email",
      tlp: 2
    });
  });
}

// Add Domains
if (input.observables?.domains?.length) {
  input.observables.domains.forEach(domain => {
    observables.push({
      dataType: "domain",
      data: domain,
      message: "Suspicious domain detected in email",
      tlp: 2
    });
  });
}

// Add Ports
if (input.observables?.ports?.length) {
  input.observables.ports.forEach(port => {
    observables.push({
      dataType: "other",
      data: port.toString(),
      message: "Suspicious port detected in URL",
      tlp: 2
    });
  });
}

// Determine severity based on suspicious indicators
let severity = 2; // Medium default
let titlePrefix = "[POSSIBLE PHISHING]";

if (input.observables?.urls?.length > 0 || input.observables?.domains?.length > 0) {
  severity = 3; // High
  titlePrefix = "[HIGH CONFIDENCE PHISHING]";
}

if (input.observables?.suspicious_texts?.length >= 3) {
  severity = 3; // Critical
  titlePrefix = "[CRITICAL PHISHING]";
}

// Build final payload for TheHive
const theHivePayload = {
  title: `${titlePrefix} ${input.email_subject || 'No Subject'}`,
  description: description,
  severity: severity,
  tags: [
    "phishing",
    "wazuh",
    `rule-${input.rule_id}`,
    ...(input.observables?.suspicious_texts?.map(t => t.category) || [])
  ],
  observables: observables
};

return theHivePayload;

