  const message = observableData.message || `Suspicious ${dataType} detected`;

  let foundCount = 0;
  let matchingEvents = [];
  let error = null;

  try {
    // Query MISP for this observable
    const response = await $http.request({
      method: "POST",
      url: mispUrl,
      headers: {
        "Authorization": apiKey,
        "Content-Type": "application/json"
      },
      body: {
        value: observable,
        type: dataType,
        returnFormat: "json"
      },
      timeout: 30000,
      continueOnFail: true
    });

    const data = response.body;

    // Parse the response
    if (data && data.response && data.response.Attribute) {
      foundCount = data.response.Attribute.length;
      matchingEvents = data.response.Attribute.map(a => a.event_id);
    } else if (Array.isArray(data)) {
