    // Format: {"response": {"Attribute": [...]}}
    foundAttributes = mispResult.response.Attribute;
  } else if (mispResult && Array.isArray(mispResult)) {
    // Format: direct array
    foundAttributes = mispResult;
  } else if (mispResult && mispResult.length === 0) {
    // Empty array - definitely not found
    foundAttributes = [];
  } else if (mispResult && mispResult.id) {
    // Single attribute returned
    foundAttributes = [mispResult];
  }

  // CLEAR DETECTION LOGIC
  // Only consider "found" if there are actual attributes with valid IDs
  const exists = foundAttributes.length > 0 && foundAttributes[0]?.event_id !== undefined;

  // Set priority based on existence
  const priority = exists ? "MEDIUM" : "HIGH";

  // Get the original observable data
