// Get all Cortex results from merge node
const cortexResults = $input.all();

// Initialize clean result objects
const cleanResults = {
  urlscan: {
    has_results: false,
    urls: [],
    ips: [],
    domains: [],
    scan_results: []
  },
  misp: {
    has_results: false,
    events: [],
    mitre_techniques: [],
    tags: []
  },
  abuse: {
    has_results: false,
    abuse_contacts: [],
    registrar: null
  },
  virustotal: {
    has_results: false,
    malicious_count: 0,
    harmless_count: 0,
    engine_results: []
  },
  ail: {
    has_results: false
  }
};

// Parse each Cortex result
for (const item of cortexResults) {
  const data = item.json;
  if (!data) continue;

  const analyzerName = data.analyzerName || '';
  const report = data.report || {};
  const full = report.full || {};

  // =============================================
  // URLSCAN.IO RESULTS
  // =============================================
  if (analyzerName.includes('Urlscan') && data.status === 'Success') {
    const indicator = full.indicator || {};
    const results = indicator.results || [];

    if (results.length > 0) {
      cleanResults.urlscan.has_results = true;

      for (const result of results) {
        const page = result.page || {};
        const task = result.task || {};

        cleanResults.urlscan.scan_results.push({
          url: page.url || task.url,
          ip: page.ip,
          domain: page.domain,
          apex_domain: page.apexDomain,
          status: page.status,
          server: page.server,
          asn: page.asn,
          country: page.country,
          screenshot: result.screenshot,
          scan_date: task.time
        });

        if (page.url) cleanResults.urlscan.urls.push(page.url);
        if (task.url) cleanResults.urlscan.urls.push(task.url);
        if (page.ip) cleanResults.urlscan.ips.push(page.ip);
        if (page.domain) cleanResults.urlscan.domains.push(page.domain);
      }

      // Remove duplicates
      cleanResults.urlscan.urls = [...new Set(cleanResults.urlscan.urls)];
      cleanResults.urlscan.ips = [...new Set(cleanResults.urlscan.ips)];
      cleanResults.urlscan.domains = [...new Set(cleanResults.urlscan.domains)];
    }
  }

  // =============================================
  // MISP RESULTS
  // =============================================
  if (analyzerName.includes('MISP') && data.status === 'Success') {
    const mispResults = full.results || [];

    for (const result of mispResults) {
      const events = result.result || [];

      for (const event of events) {
        cleanResults.misp.has_results = true;
        cleanResults.misp.events.push({
          id: event.id,
          info: event.info,
          date: event.date,
          threat_level: event.threat_level_id,
          event_creator: event.event_creator_email,
          related_events: (event.RelatedEvent || []).length
        });

        // Extract MITRE techniques from Galaxy clusters
        const galaxies = event.Galaxy || [];
        for (const galaxy of galaxies) {
          const clusters = galaxy.GalaxyCluster || [];
          for (const cluster of clusters) {
            cleanResults.misp.mitre_techniques.push({
              technique: cluster.value,
              type: cluster.type,
              description: cluster.description ? cluster.description.substring(0, 200) : '',
              tag: cluster.tag_name
            });
          }
        }

        // Extract tags
        const tags = event.Tag || [];
        for (const tag of tags) {
          if (tag.name && !cleanResults.misp.tags.includes(tag.name)) {
            cleanResults.misp.tags.push(tag.name);
          }
        }
      }
    }

    // Remove duplicate MITRE techniques
    const uniqueMitre = [];
    const seen = new Set();
    for (const tech of cleanResults.misp.mitre_techniques) {
      if (!seen.has(tech.technique)) {
        seen.add(tech.technique);
        uniqueMitre.push(tech);
      }
    }
    cleanResults.misp.mitre_techniques = uniqueMitre;
  }

  // =============================================
  // ABUSE FINDER RESULTS
  // =============================================
  if (analyzerName.includes('Abuse_Finder') && data.status === 'Success') {
    const abuseFinder = full.abuse_finder || {};

    if (abuseFinder.value) {
      cleanResults.abuse.has_results = true;
      cleanResults.abuse.abuse_contacts = abuseFinder.abuse || [];
      cleanResults.abuse.registrar = (abuseFinder.names || [])[0] || null;
      cleanResults.abuse.domain = abuseFinder.value;
    }
  }

  // =============================================
  // VIRUSTOTAL RESULTS
  // =============================================
  if (analyzerName.includes('VirusTotal') && data.status === 'Success') {
    const vtData = full;

    if (vtData.type === 'domain' && vtData.attributes) {
      const stats = vtData.attributes.last_analysis_stats || {};
      cleanResults.virustotal.has_results = true;
      cleanResults.virustotal.malicious_count = stats.malicious || 0;
      cleanResults.virustotal.harmless_count = stats.harmless || 0;
      cleanResults.virustotal.suspicious_count = stats.suspicious || 0;
      cleanResults.virustotal.domain = vtData.id;
      cleanResults.virustotal.reputation = vtData.attributes.reputation;

      // Extract malicious engine results
      const analysisResults = vtData.attributes.last_analysis_results || {};
      for (const [engine, result] of Object.entries(analysisResults)) {
        if (result.category === 'malicious') {
          cleanResults.virustotal.engine_results.push({
            engine: engine,
            result: result.result,
            category: result.category
          });
        }
      }
    }
  }

  // =============================================
  // AIL RESULTS (onion links)
  // =============================================
  if (analyzerName.includes('AIL') && data.status === 'Success') {
    cleanResults.ail.has_results = true;
    cleanResults.ail.data = full;
  }
}

