if (cleanResults.virustotal.malicious_count > 5) threatScore += 20;
if (cleanResults.abuse.has_results) threatScore += 5;

if (threatScore >= 60) threatLevel = 'CRITICAL';
else if (threatScore >= 40) threatLevel = 'HIGH';
else if (threatScore >= 20) threatLevel = 'MEDIUM';
else threatLevel = 'LOW';

// Determine if action is needed
const requiresAction = threatLevel === 'CRITICAL' || threatLevel === 'HIGH' || 
