let keyFindings = [];
let immediateMitigations = {
  firewall: '',
  email_filter: '',
  user_action: ''
};
let advancedCountermeasures = [];

if (aiResponse) {
  const verdictMatch = aiResponse.match(/REVISED VERDICT:\s*(\w+)/i);
  if (verdictMatch) revisedVerdict = verdictMatch[1];

  const riskMatch = aiResponse.match(/REVISED RISK SCORE:\s*(\d+)/i);
  if (riskMatch) revisedRiskScore = riskMatch[1];

  const assessmentMatch = aiResponse.match(/THREAT ASSESSMENT:\s*([\s\S]*?)(?=KEY FINDINGS:|$)/i);
  if (assessmentMatch) threatAssessment = assessmentMatch[1].trim();

  const findingsMatch = aiResponse.match(/KEY FINDINGS:\s*([\s\S]*?)(?=IMMEDIATE MITIGATIONS:|$)/i);
  if (findingsMatch) {
    const findingsText = findingsMatch[1];
    keyFindings = findingsText.split(/\d+\./).filter(f => f.trim()).map(f => f.trim());
  }

  const mitigationsMatch = aiResponse.match(/IMMEDIATE MITIGATIONS:\s*([\s\S]*?)(?=ADVANCED COUNTERMEASURES:|$)/i);
  if (mitigationsMatch) {
    const mitigationsText = mitigationsMatch[1];
    const firewallMatch = mitigationsText.match(/Firewall action:\s*(.+)/i);
    const emailMatch = mitigationsText.match(/Email filter action:\s*(.+)/i);
    const userMatch = mitigationsText.match(/User action:\s*(.+)/i);

    if (firewallMatch) immediateMitigations.firewall = firewallMatch[1];
    if (emailMatch) immediateMitigations.email_filter = emailMatch[1];
    if (userMatch) immediateMitigations.user_action = userMatch[1];
  }

  const counterMatch = aiResponse.match(/ADVANCED COUNTERMEASURES:\s*([\s\S]*?)$/i);
  if (counterMatch) {
    const counterText = counterMatch[1];
    advancedCountermeasures = counterText.split(/\d+\./).filter(c => c.trim()).map(c => c.trim());
  }
}

// Use revised values if available, but ensure we use the AI verdict if it's more accurate
