parameters.jsCode:
// Get all observables from the previous node
const observables = $input.all();

// Define analyzers for each data type
const analyzersByType = {
  ip: ["MISP_2_1"],
  domain: ["MISP_2_1"],
  url: ["MISP_2_1"]
};

const allJobs = [];

for (const item of observables) {
  const observable = item.json;

  const artifactId = observable.id;
  const dataType = observable.data_type;
  const data = observable.observable;
  const message = observable.message;

  if (!data || !dataType) {
    console.log(`Skipping - missing data or type`);
    continue;
  }

  const analyzers = analyzersByType[dataType] || [];

  for (const analyzerId of analyzers) {
    allJobs.push({
      artifactId: artifactId,
      analyzerId: analyzerId,
      cortexId: "cortex0",
      observableData: data,
      dataType: dataType,
      message: message,
      analyzerPurpose: "Query MISP for existing intelligence"
    });
  }
}

console.log(`Created ${allJobs.length} MISP jobs`);
return allJobs.map(job => ({ json: job }));
